            self.validation.terminate_children()
            self.report("complete")


def main() -> int:
    try:
        return Harness().run()
    except (ModelUnavailable, KeyError, ValueError) as error:
        log("configuration_error", error=str(error))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
