class Validation:
    def __init__(self, workspace: Path, scratch: Path, deadline: float,
                 stop: threading.Event):
        self.workspace = Path(workspace).resolve()
        self.scratch = Path(scratch).resolve()
        self.scratch.mkdir(parents=True, exist_ok=True)
